-- Update ket_barang untuk produk stok_barang > 0, batch 3 (99 produk)
-- Jalankan di tab SQL phpMyAdmin pada database `berlian`

UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Pirantel Pamoat setara Pirantel base 125 mg<br />\r\nIndikasi :<br />\r\nUntuk mengatasi infeksi cacing gelang (Ascaris lumbricoides), cacing kremi (Enterobius vermicularis), dan cacing tambang<br />\r\nEfek Samping :<br />\r\nMual, muntah, diare, sakit kepala, atau pusing (jarang terjadi)<br />\r\nAturan Pakai :<br />\r\nKocok botol terlebih dahulu sebelum digunakan. Dosis 10 mg/kgBB diminum sekali sehari (dosis tunggal), dapat diulang setelah 2 minggu bila perlu, atau sesuai anjuran dokter/apoteker<br />\r\n&nbsp;</p>' WHERE `id_barang` = 57;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMetformin HCl 500 mg<br />\r\nIndikasi :<br />\r\nTerapi diabetes melitus tipe 2, khususnya pada pasien dengan kelebihan berat badan (obesitas), sebagai monoterapi atau kombinasi dengan antidiabetes lain maupun insulin<br />\r\nEfek Samping :<br />\r\nMual, muntah, diare, kembung, nyeri perut, penurunan nafsu makan, atau rasa logam di mulut<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet, 2-3 kali sehari bersama atau setelah makan, dosis disesuaikan oleh dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 184;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPermetrin (Permethrin) 5%<br />\r\nIndikasi :<br />\r\nUntuk mengobati infestasi tungau penyebab kudis/skabies (scabies)<br />\r\nEfek Samping :<br />\r\nRasa panas, perih, kemerahan, gatal, atau kesemutan sementara pada kulit setelah pemakaian<br />\r\nAturan Pakai :<br />\r\nOleskan tipis merata ke seluruh permukaan kulit tubuh (kecuali wajah) setelah mandi, diamkan 8-14 jam lalu bilas hingga bersih. Dosis dewasa/lansia/anak &gt;12 tahun maksimal 30 g, anak 6-12 tahun maksimal 15 g, anak &lt;6 tahun maksimal 7,5 g, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 219;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nEperisone HCl 50 mg<br />\r\nIndikasi :<br />\r\nPelemas otot (muscle relaxant) untuk meredakan kekakuan dan spasme otot pada gangguan muskuloskeletal seperti nyeri leher/bahu/pinggang, serta spastisitas otot<br />\r\nEfek Samping :<br />\r\nMengantuk, lemas, mual, gangguan pencernaan; jarang, reaksi alergi<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet, 3 kali sehari setelah makan, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 222;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCefadroxil Monohydrate setara Cefadroxil 500 mg<br />\r\nIndikasi :<br />\r\nAntibiotik golongan sefalosporin untuk infeksi saluran kemih, infeksi saluran napas, serta infeksi kulit dan jaringan lunak yang disebabkan bakteri yang peka<br />\r\nEfek Samping :<br />\r\nMual, muntah, diare, ruam kulit, atau reaksi alergi<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kapsul, 2 kali sehari. Habiskan sesuai anjuran dokter meskipun gejala sudah membaik, untuk mencegah resistensi antibiotik<br />\r\n&nbsp;</p>' WHERE `id_barang` = 224;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Paracetamol, Succus Liquiritiae, Pseudoephedrine HCl, Chlorpheniramine Maleate, dan Ammonium Chloride<br />\r\nIndikasi :<br />\r\nMeredakan gejala flu pada anak seperti batuk berdahak, pilek, bersin-bersin, demam ringan, hidung tersumbat, dan pusing<br />\r\nEfek Samping :<br />\r\nMulut kering, mengantuk, retensi urin, jantung berdebar; kerusakan hati bila paracetamol digunakan berlebihan<br />\r\nAturan Pakai :<br />\r\nKocok dahulu sebelum digunakan. Anak 2-6 tahun: 5 ml, 3 kali sehari. Anak 6-12 tahun: 10 ml, 3 kali sehari. Tidak untuk anak di bawah 2 tahun<br />\r\n&nbsp;</p>' WHERE `id_barang` = 914;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nHydrogel sheet (lembaran gel pendingin) mengandung air, polimer penyerap, mentol, dan bahan pendingin lainnya, bebas obat (non-drug)<br />\r\nIndikasi :<br />\r\nMembantu menurunkan panas/demam secara topikal pada anak, meredakan pegal dan memberikan rasa sejuk pada dahi<br />\r\nEfek Samping :<br />\r\nUmumnya aman; hentikan pemakaian bila timbul iritasi atau kemerahan pada kulit<br />\r\nAturan Pakai :<br />\r\nTempelkan lembaran gel pada dahi yang bersih dan kering, dapat digunakan hingga 8 jam, ganti dengan lembaran baru bila diperlukan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 1150;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nKapas/tisu non woven 2 ply yang dibasahi larutan Isopropil Alkohol 70%<br />\r\nIndikasi :<br />\r\nUntuk membersihkan dan mendisinfeksi permukaan kulit sebelum penyuntikan, pengambilan darah, atau tindakan medis lainnya<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan rasa perih atau iritasi ringan pada kulit sensitif; hindari kontak dengan mata dan luka terbuka<br />\r\nAturan Pakai :<br />\r\nUsapkan satu lembar alkohol swab pada area kulit yang akan ditindak, sekali pakai lalu buang<br />\r\n&nbsp;</p>' WHERE `id_barang` = 1220;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSabun cair antiseptik dengan bahan aktif Triclosan/Chloroxylenol (sesuai varian), surfaktan pembersih, dan pewangi<br />\r\nIndikasi :<br />\r\nMembersihkan dan menyegarkan kulit tubuh sehari-hari serta membantu mengurangi kuman penyebab bau badan<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan iritasi pada kulit sensitif; hentikan pemakaian bila timbul kemerahan atau gatal<br />\r\nAturan Pakai :<br />\r\nGunakan secukupnya saat mandi, usapkan merata ke seluruh tubuh lalu bilas hingga bersih<br />\r\n&nbsp;</p>' WHERE `id_barang` = 1300;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nJasa/alat pemeriksaan kadar glukosa darah menggunakan strip test dan alat glukometer, non-obat<br />\r\nIndikasi :<br />\r\nUntuk mengetahui kadar gula darah sewaktu sebagai skrining atau pemantauan diabetes melitus<br />\r\nEfek Samping :<br />\r\nTindakan tusuk jari (lancet) dapat menimbulkan nyeri ringan dan sedikit memar pada titik tusukan<br />\r\nAturan Pakai :<br />\r\nDilakukan oleh petugas apotek dengan menusuk ujung jari menggunakan lancet steril, sampel darah dibaca oleh alat glukometer<br />\r\n&nbsp;</p>' WHERE `id_barang` = 1425;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nJasa/alat pemeriksaan kadar asam urat darah menggunakan strip test dan alat meter, non-obat<br />\r\nIndikasi :<br />\r\nUntuk mengetahui kadar asam urat dalam darah sebagai skrining atau pemantauan risiko gout/asam urat tinggi<br />\r\nEfek Samping :<br />\r\nTindakan tusuk jari (lancet) dapat menimbulkan nyeri ringan dan sedikit memar pada titik tusukan<br />\r\nAturan Pakai :<br />\r\nDilakukan oleh petugas apotek dengan menusuk ujung jari menggunakan lancet steril, sampel darah dibaca oleh alat meter asam urat<br />\r\n&nbsp;</p>' WHERE `id_barang` = 1426;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nJasa/alat pemeriksaan kadar kolesterol total darah menggunakan strip test dan alat meter, non-obat<br />\r\nIndikasi :<br />\r\nUntuk mengetahui kadar kolesterol total dalam darah sebagai skrining atau pemantauan risiko penyakit jantung<br />\r\nEfek Samping :<br />\r\nTindakan tusuk jari (lancet) dapat menimbulkan nyeri ringan dan sedikit memar pada titik tusukan<br />\r\nAturan Pakai :<br />\r\nDilakukan oleh petugas apotek dengan menusuk ujung jari menggunakan lancet steril, sampel darah dibaca oleh alat meter kolesterol<br />\r\n&nbsp;</p>' WHERE `id_barang` = 1427;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nKain kasa katun steril ukuran 16 x 16 cm, non-obat<br />\r\nIndikasi :<br />\r\nUntuk menutup dan melindungi luka, menyerap cairan/darah dari luka, serta sebagai alas pada tindakan perawatan luka<br />\r\nEfek Samping :<br />\r\nUmumnya aman digunakan; pastikan luka dan area sekitarnya bersih sebelum penggunaan untuk mencegah infeksi<br />\r\nAturan Pakai :<br />\r\nBuka kemasan steril, tempelkan kasa pada luka yang telah dibersihkan, fiksasi dengan plester atau perban, ganti secara berkala<br />\r\n&nbsp;</p>' WHERE `id_barang` = 1597;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap sachet mengandung campuran probiotik Lactobacillus casei, Lactobacillus salivarius, Lactobacillus acidophilus, Bifidobacterium longum, Bifidobacterium lactis, Bifidobacterium infantis, Lactococcus lactis, dengan basis rice starch dan maltodekstrin<br />\r\nIndikasi :<br />\r\nMembantu mengatasi gangguan pencernaan seperti diare dan sembelit dengan memperbaiki keseimbangan bakteri baik dalam usus<br />\r\nEfek Samping :<br />\r\nBelum ada laporan efek samping yang berarti; konsumsi berlebihan dapat menyebabkan kembung atau gangguan pencernaan ringan<br />\r\nAturan Pakai :<br />\r\nAnak &gt;2 tahun: 2-3 sachet sehari. Anak 1-2 tahun: 1-2 sachet sehari. Dapat dikonsumsi langsung atau dicampur susu/makanan, sebelum atau sesudah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 1926;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPrednisone 5 mg<br />\r\nIndikasi :<br />\r\nKortikosteroid untuk meredakan peradangan dan reaksi alergi pada berbagai kondisi seperti asma, radang sendi (artritis), penyakit autoimun, dan alergi berat<br />\r\nEfek Samping :<br />\r\nPeningkatan nafsu makan dan berat badan, retensi cairan, gangguan lambung, perubahan mood, penurunan daya tahan tubuh pada penggunaan jangka panjang<br />\r\nAturan Pakai :<br />\r\nDiminum sesuai dosis dan jadwal yang ditentukan dokter, umumnya bersama makanan; jangan dihentikan mendadak tanpa anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2014;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nLarutan Natrium Klorida (Sodium Chloride) 0,9% isotonis, steril, bebas pirogen<br />\r\nIndikasi :<br />\r\nCairan infus untuk mengganti cairan dan elektrolit tubuh, mengatasi dehidrasi, serta sebagai pelarut/pengencer obat suntik; juga digunakan untuk mencuci luka atau irigasi<br />\r\nEfek Samping :<br />\r\nReaksi pada tempat penyuntikan seperti iritasi atau infeksi; kelebihan cairan dapat menyebabkan bengkak bila diberikan berlebihan<br />\r\nAturan Pakai :<br />\r\nDigunakan sesuai petunjuk dan pengawasan tenaga medis, melalui infus intravena atau untuk mencuci luka/irigasi pada pemakaian luar<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2069;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nIsopropil Alkohol/Etanol 70%<br />\r\nIndikasi :<br />\r\nAntiseptik untuk membersihkan dan mendisinfeksi kulit sebelum tindakan medis, serta untuk membersihkan permukaan alat kesehatan<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan iritasi dan rasa perih pada kulit sensitif atau luka terbuka; mudah terbakar, jauhkan dari api<br />\r\nAturan Pakai :<br />\r\nTuangkan secukupnya pada kapas, usapkan pada area kulit yang akan dibersihkan; hanya untuk pemakaian luar<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2079;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCefixime Trihydrate setara Cefixime 200 mg<br />\r\nIndikasi :<br />\r\nAntibiotik golongan sefalosporin untuk infeksi saluran kemih, infeksi saluran napas, otitis media, dan faringitis/tonsilitis yang disebabkan bakteri yang peka<br />\r\nEfek Samping :<br />\r\nMual, muntah, diare, nyeri perut, ruam kulit<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kapsul, 2 kali sehari, dihabiskan sesuai resep dokter meskipun gejala sudah membaik untuk mencegah resistensi antibiotik<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2234;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Dextromethorphan HBr 10 mg, Diphenhydramine HCl 12,5 mg, Ammonium Chloride 100 mg, Natrium Sitrat 50 mg, Menthol 1 mg<br />\r\nIndikasi :<br />\r\nMeredakan batuk berdahak yang menimbulkan rasa tidak nyaman atau batuk karena alergi<br />\r\nEfek Samping :<br />\r\nMengantuk, sedasi, pusing, gangguan koordinasi, rasa tidak enak pada ulu hati<br />\r\nAturan Pakai :<br />\r\nDewasa: 2 sendok takar (10 ml), 3-4 kali sehari. Anak 6-12 tahun: 1 sendok takar (5 ml), 3-4 kali sehari, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2254;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Dextromethorphan HBr 5 mg, Guaifenesin 25 mg, Pseudoephedrine HCl 7,5 mg, Chlorpheniramine Maleate 0,5 mg<br />\r\nIndikasi :<br />\r\nMeredakan gejala flu seperti hidung tersumbat, bersin-bersin, disertai batuk<br />\r\nEfek Samping :<br />\r\nMual, muntah ringan, sakit kepala, mengantuk, pusing, mulut kering; jarang, gangguan irama jantung<br />\r\nAturan Pakai :<br />\r\nAnak 2-5 tahun: 1 sendok takar (5 ml), 3 kali sehari. Anak 6-12 tahun: 2 sendok takar (10 ml), 3 kali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2376;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Pseudoephedrine HCl 15 mg, Chlorpheniramine Maleate 1 mg<br />\r\nIndikasi :<br />\r\nMelegakan bersin-bersin dan hidung tersumbat akibat pilek/flu<br />\r\nEfek Samping :<br />\r\nInsomnia, sakit kepala, gelisah, tremor, jantung berdebar cepat, sulit buang air kecil<br />\r\nAturan Pakai :<br />\r\nAnak 2-5 tahun: 2,5 ml (&frac12; sendok takar), 3 kali sehari. Anak 6-12 tahun: 5 ml, 3 kali sehari. Anak &gt;12 tahun dan dewasa: 10 ml, 3 kali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2388;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nGlibenclamide 5 mg<br />\r\nIndikasi :<br />\r\nMengendalikan kadar gula darah tinggi pada diabetes melitus tipe 2<br />\r\nEfek Samping :<br />\r\nBerat badan meningkat, mual, rasa panas di ulu hati, perut kembung, dan risiko hipoglikemia (gula darah rendah)<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kali sehari saat sarapan, dosis dapat disesuaikan bertahap oleh dokter hingga maksimal 20 mg/hari; dosis di atas 10 mg/hari dapat dibagi 2 kali pemberian<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2496;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAsetosal (Acetylsalicylic Acid/Aspirin) 80 mg per tablet kunyah<br />\r\nIndikasi :<br />\r\nMenurunkan demam dan meredakan nyeri ringan pada anak, termasuk demam setelah imunisasi<br />\r\nEfek Samping :<br />\r\nIritasi lambung, mual, muntah; penggunaan jangka panjang berisiko perdarahan saluran cerna dan tukak lambung<br />\r\nAturan Pakai :<br />\r\nUsia 2-3 tahun: 1 tablet. Usia 4-5 tahun: 2 tablet. Usia 6-8 tahun: 3 tablet. Dapat diulang tiap 4 jam bila perlu, atau sesuai anjuran dokter. PERHATIAN: karena mengandung Asetosal (golongan salisilat), sebaiknya digunakan dengan resep/anjuran dokter dan tidak digunakan pada anak yang sedang mengalami infeksi virus (cacar air/flu) karena berisiko Sindrom Reye<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2505;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSucralfate 500 mg/ 5 ml<br />\r\nIndikasi :<br />\r\nMengobati tukak lambung dan tukak usus dua belas jari (duodenum), serta melindungi lapisan mukosa lambung<br />\r\nEfek Samping :<br />\r\nSembelit (konstipasi), mual, mulut kering, gangguan pencernaan ringan<br />\r\nAturan Pakai :<br />\r\nKocok dahulu sebelum digunakan. Diminum 1 sendok takar (5-10 ml), 2-4 kali sehari, sebaiknya saat perut kosong (1 jam sebelum makan dan sebelum tidur), atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2515;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nLansoprazole 30 mg<br />\r\nIndikasi :<br />\r\nMengatasi tukak lambung, tukak duodenum, GERD (refluks asam lambung), dan infeksi H. pylori (kombinasi dengan antibiotik)<br />\r\nEfek Samping :<br />\r\nSakit kepala, diare, mual, nyeri perut, konstipasi<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kapsul sehari, sebaiknya sebelum makan pagi, ditelan utuh tanpa dikunyah, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2517;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Succus Liquiritiae 100 mg, Paracetamol 120 mg, Ammonium Chloride 50 mg, Pseudoephedrine HCl 7,5 mg, Chlorpheniramine Maleate 1 mg<br />\r\nIndikasi :<br />\r\nMeredakan gejala flu pada anak seperti demam, sakit kepala, bersin-bersin, dan hidung tersumbat disertai batuk<br />\r\nEfek Samping :<br />\r\nMengantuk<br />\r\nAturan Pakai :<br />\r\nAnak 2-5 tahun: 1 sendok takar (5 ml), 3 kali sehari. Anak 6-12 tahun: 2 sendok takar (10 ml), 3 kali sehari. Tidak untuk anak di bawah 2 tahun<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2525;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Paracetamol 120 mg, Phenylephrine HCl 2,5 mg, Guaifenesin 25 mg, Bromhexine HCl 2 mg, Chlorpheniramine Maleate 1 mg<br />\r\nIndikasi :<br />\r\nMeredakan gejala flu pada anak seperti demam, sakit kepala, hidung tersumbat, dan bersin-bersin disertai batuk berdahak<br />\r\nEfek Samping :<br />\r\nMengantuk, gangguan pencernaan, gangguan koordinasi, jantung berdebar, mulut kering, sulit buang air kecil, pusing<br />\r\nAturan Pakai :<br />\r\nAnak 6-12 tahun: 2 sendok takar (10 ml), 3 kali sehari sesudah makan. Anak di bawah 6 tahun sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2550;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDextromethorphan HBr 15 mg, Glyceryl Guaiacolate 100 mg, Diphenhydramine HCl 5 mg<br />\r\nIndikasi :<br />\r\nMeredakan batuk, hidung tersumbat, bersin-bersin, dan gatal tenggorokan akibat alergi<br />\r\nEfek Samping :<br />\r\nMengantuk, gangguan pencernaan, mulut kering, pusing<br />\r\nAturan Pakai :<br />\r\nDewasa dan anak &gt;12 tahun: 1-2 tablet, 3 kali sehari. Anak 6-12 tahun: &frac12;-1 tablet, 3 kali sehari. Anak 3-6 tahun: &frac14;-&frac12; tablet, 3 kali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2689;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nVitamin D3 (Cholecalciferol) 1000 IU<br />\r\nIndikasi :<br />\r\nMembantu memenuhi kebutuhan vitamin D3 untuk mendukung kesehatan tulang dan daya tahan tubuh<br />\r\nEfek Samping :<br />\r\nUmumnya aman pada dosis anjuran; kelebihan dosis jangka panjang berisiko hiperkalsemia<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet sehari setelah makan, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2691;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMefenamic Acid (Asam Mefenamat) 500 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri ringan hingga sedang seperti sakit gigi, nyeri haid, nyeri otot, dan nyeri sendi<br />\r\nEfek Samping :<br />\r\nMual, gangguan pencernaan, nyeri ulu hati, pusing, atau mengantuk<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kaplet, 3 kali sehari sesudah makan, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2761;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDibasic Calcium Phosphate 500 mg per tablet kunyah<br />\r\nIndikasi :<br />\r\nMemenuhi kebutuhan kalsium harian serta menjaga kesehatan tulang dan gigi, terutama pada vegetarian, masa menopause, penggunaan kortikosteroid jangka panjang, atau gangguan penyerapan kalsium<br />\r\nEfek Samping :<br />\r\nKembung, mual/muntah, penurunan nafsu makan, sembelit, sering buang air kecil, mulut kering; jarang, reaksi alergi atau hiperkalsemia (bingung, jantung berdebar, lemas) bila berlebihan<br />\r\nAturan Pakai :<br />\r\nDewasa: 2-4 tablet, 2 kali sehari. Anak: 1-2 tablet, 2 kali sehari. Tablet dikunyah lalu diminum dengan air, sebaiknya bersama makanan; beri jarak minimal 2 jam dari suplemen zat besi<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2777;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nKondom lateks karet alami, dilumasi (lubricated), non-obat, alat kontrasepsi<br />\r\nIndikasi :<br />\r\nAlat kontrasepsi pria sekali pakai untuk mencegah kehamilan dan mengurangi risiko penularan penyakit menular seksual<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan reaksi alergi pada individu yang sensitif terhadap lateks<br />\r\nAturan Pakai :<br />\r\nGunakan satu kondom untuk sekali pemakaian, pasang sebelum berhubungan intim sesuai petunjuk pada kemasan, periksa tanggal kedaluwarsa sebelum digunakan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2968;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nKondom lateks karet alami, dilumasi (lubricated), non-obat, alat kontrasepsi<br />\r\nIndikasi :<br />\r\nAlat kontrasepsi pria sekali pakai untuk mencegah kehamilan dan mengurangi risiko penularan penyakit menular seksual<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan reaksi alergi pada individu yang sensitif terhadap lateks<br />\r\nAturan Pakai :<br />\r\nGunakan satu kondom untuk sekali pemakaian, pasang sebelum berhubungan intim sesuai petunjuk pada kemasan, periksa tanggal kedaluwarsa sebelum digunakan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2970;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMinyak Kelapa, Minyak Kayu Putih (Cajuput Oil), Minyak Adas (Fennel Oil), Oleum Eucalyptus, dengan Vitamin E<br />\r\nIndikasi :<br />\r\nMemberikan rasa hangat pada tubuh bayi, membantu meredakan masuk angin/perut kembung, serta melembapkan kulit bayi saat pijat<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan iritasi kulit ringan pada bayi dengan kulit sensitif<br />\r\nAturan Pakai :<br />\r\nOleskan dan pijat lembut secukupnya pada perut, dada, dan punggung bayi, dapat digunakan setelah mandi atau sebelum tidur<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2990;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPermetrin (Permethrin) 5%<br />\r\nIndikasi :<br />\r\nUntuk mengobati infestasi tungau penyebab kudis/skabies (scabies)<br />\r\nEfek Samping :<br />\r\nRasa panas, perih, kemerahan, gatal, atau kesemutan sementara pada kulit setelah pemakaian<br />\r\nAturan Pakai :<br />\r\nOleskan tipis merata ke seluruh permukaan kulit tubuh (kecuali wajah) setelah mandi, diamkan 8-14 jam lalu bilas hingga bersih. Dosis dewasa/lansia/anak &gt;12 tahun maksimal 30 g, anak 6-12 tahun maksimal 15 g, anak &lt;6 tahun maksimal 7,5 g, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2995;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTretinoin 0,025%<br />\r\nIndikasi :<br />\r\nMengatasi jerawat (akne vulgaris) dengan mengurangi penyumbatan pori dan membantu regenerasi kulit<br />\r\nEfek Samping :<br />\r\nKulit kemerahan, perih, mengelupas, dan lebih sensitif terhadap sinar matahari, terutama di awal pemakaian<br />\r\nAturan Pakai :<br />\r\nOleskan tipis pada area berjerawat 1 kali sehari pada malam hari, hindari area mata dan bibir. Gunakan tabir surya di siang hari karena kulit menjadi lebih sensitif terhadap matahari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 2998;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPlester hangat (koyo) mengandung Capsaicin/ekstrak cabai, Methyl Salicylate, dan Menthol<br />\r\nIndikasi :<br />\r\nMeredakan pegal linu, nyeri otot, dan nyeri sendi ringan dengan memberikan sensasi hangat<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan rasa panas berlebih, iritasi, atau kemerahan pada kulit sensitif; jangan gunakan pada kulit luka<br />\r\nAturan Pakai :<br />\r\nTempelkan pada area yang nyeri, gunakan maksimal 1-2 kali sehari, jangan digunakan lebih dari 8 jam berturut-turut<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3024;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nParacetamol 650 mg, Guaifenesin 50 mg, Phenylpropanolamine HCl 15 mg, Chlorpheniramine Maleate 2 mg<br />\r\nIndikasi :<br />\r\nMeredakan gejala flu seperti demam, sakit kepala, hidung tersumbat, dan bersin-bersin disertai batuk<br />\r\nEfek Samping :<br />\r\nMengantuk, gangguan pencernaan, jantung berdebar<br />\r\nAturan Pakai :<br />\r\nDewasa: 1 tablet, 3-4 kali sehari. Anak 6-12 tahun: &frac12; tablet, 3-4 kali sehari. Diminum sebelum atau sesudah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3063;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nKalium Diklofenak (Diclofenac Potassium) 50 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri dan peradangan pada artritis (rheumatoid arthritis, osteoarthritis), nyeri gigi, migrain akut, nyeri haid, dan nyeri pascaoperasi<br />\r\nEfek Samping :<br />\r\nMual, muntah, sembelit, nyeri perut, diare; jarang, gangguan fungsi hati atau reaksi alergi kulit<br />\r\nAturan Pakai :<br />\r\nDewasa: dosis awal 100-150 mg sehari, dibagi 2-3 kali pemberian. Diminum bersama makanan untuk mengurangi iritasi lambung, sesuai resep dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3131;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap lembar mengandung Methyl Salicylate 10%, Menthol 3%, dan bahan pendingin lainnya (varian hijau/cooling)<br />\r\nIndikasi :<br />\r\nMeredakan nyeri otot, pegal-pegal, nyeri sendi, dan keseleo ringan<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan iritasi kulit, rasa panas/dingin berlebih, atau kemerahan pada kulit sensitif<br />\r\nAturan Pakai :<br />\r\nTempelkan pada area yang nyeri 1-2 kali sehari, jangan gunakan pada kulit luka atau iritasi<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3181;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDexamethasone 0,75 mg<br />\r\nIndikasi :<br />\r\nKortikosteroid untuk meredakan peradangan dan reaksi alergi berat, seperti asma, rhinitis alergi, dan penyakit autoimun<br />\r\nEfek Samping :<br />\r\nPeningkatan nafsu makan dan berat badan, retensi cairan, gangguan lambung, penurunan daya tahan tubuh pada penggunaan jangka panjang<br />\r\nAturan Pakai :<br />\r\nDiminum sesuai dosis dan jadwal yang ditentukan dokter, bersama makanan; jangan dihentikan mendadak tanpa anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3208;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDexamethasone 0,5 mg<br />\r\nIndikasi :<br />\r\nKortikosteroid untuk meredakan peradangan dan reaksi alergi berat, seperti asma, rhinitis alergi, dan penyakit autoimun<br />\r\nEfek Samping :<br />\r\nPeningkatan nafsu makan dan berat badan, retensi cairan, gangguan lambung, penurunan daya tahan tubuh pada penggunaan jangka panjang<br />\r\nAturan Pakai :<br />\r\nDiminum sesuai dosis dan jadwal yang ditentukan dokter, bersama makanan; jangan dihentikan mendadak tanpa anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3273;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nNatrium Diklofenak (Diclofenac Sodium) 50 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri akibat peradangan sendi (artritis), cedera, nyeri pascaoperasi, atau nyeri akut lainnya<br />\r\nEfek Samping :<br />\r\nSakit perut atau maag, tekanan darah meningkat; jarang, gangguan fungsi hati/ginjal<br />\r\nAturan Pakai :<br />\r\nDiminum tiap 8 jam setelah makan, ditelan utuh dengan segelas air, atau sesuai resep dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3279;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nKetoconazole 2%<br />\r\nIndikasi :<br />\r\nMengobati infeksi jamur pada kulit seperti panu, kurap, kutu air, dan kandidiasis kulit<br />\r\nEfek Samping :<br />\r\nIritasi, rasa terbakar, kemerahan, atau gatal pada area yang diolesi<br />\r\nAturan Pakai :<br />\r\nOleskan tipis merata pada area kulit yang terinfeksi 1-2 kali sehari, dilanjutkan beberapa hari setelah gejala hilang untuk mencegah kekambuhan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3289;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Zinc Sulfate Monohydrate 5 mg, Vitamin C (Ascorbic Acid) 40 mg<br />\r\nIndikasi :<br />\r\nSuplementasi zinc dan vitamin C untuk membantu menjaga daya tahan tubuh anak<br />\r\nEfek Samping :<br />\r\nPusing, sakit kepala, asam lambung naik, kram perut, mual, muntah, diare, atau rasa logam di lidah<br />\r\nAturan Pakai :<br />\r\nAnak 2-6 tahun: 2,5 ml (&frac12; sendok takar). Anak 7-12 tahun: 5 ml (1 sendok takar), sesuai anjuran pada kemasan atau dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3305;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nOmeprazole 20 mg<br />\r\nIndikasi :<br />\r\nMengatasi tukak lambung, tukak duodenum, GERD (refluks asam lambung), dan sindrom Zollinger-Ellison<br />\r\nEfek Samping :<br />\r\nSakit kepala, mual, diare, nyeri perut, konstipasi<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kapsul sehari sebelum makan, ditelan utuh tanpa dikunyah, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3307;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMefenamic Acid (Asam Mefenamat) 500 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri ringan hingga sedang seperti sakit gigi, nyeri haid, sakit kepala, dan nyeri otot/sendi<br />\r\nEfek Samping :<br />\r\nMual, gangguan pencernaan, nyeri ulu hati, pusing, mengantuk<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kaplet, 3 kali sehari sesudah makan, tidak digunakan lebih dari 7 hari tanpa anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3314;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nKalium Diklofenak (Diclofenac Potassium) 50 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri dan peradangan pada artritis, nyeri gigi, migrain, nyeri haid, dan nyeri pascaoperasi<br />\r\nEfek Samping :<br />\r\nRetensi cairan dan natrium (bengkak), tekanan darah meningkat, sakit kepala, pusing, mual, muntah, nyeri perut<br />\r\nAturan Pakai :<br />\r\nDewasa: 50 mg, 2-3 kali sehari. Diminum bersama makanan, sesuai resep dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3328;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSabun batang dengan ekstrak Pepaya (Papaya Extract), Vitamin E, dan bahan pencerah kulit lainnya<br />\r\nIndikasi :<br />\r\nMembantu membersihkan, mencerahkan, dan menghaluskan kulit wajah dan tubuh<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan iritasi atau alergi pada kulit sensitif; hentikan pemakaian bila timbul kemerahan atau gatal<br />\r\nAturan Pakai :<br />\r\nBasahi kulit, usapkan sabun hingga berbusa, pijat lembut, lalu bilas hingga bersih; gunakan secara rutin 2 kali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3372;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nGentamicin Sulfate 1 mg dan Betamethasone Valerate 1 mg per gram krim<br />\r\nIndikasi :<br />\r\nMengobati peradangan kulit yang disertai infeksi bakteri, seperti dermatitis, psoriasis, dan eksim<br />\r\nEfek Samping :<br />\r\nRasa gatal, perih, atau panas; penipisan kulit, pertumbuhan rambut berlebih, atau perubahan warna kulit pada pemakaian jangka panjang<br />\r\nAturan Pakai :<br />\r\nOleskan tipis merata pada kulit yang terinfeksi 2-3 kali sehari, tidak untuk anak di bawah 2 tahun, hindari pemakaian jangka panjang tanpa anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3432;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nEkstrak Ikan Gabus (Channa striata) sebagai sumber albumin alami<br />\r\nIndikasi :<br />\r\nMembantu memenuhi kebutuhan protein albumin tubuh, membantu proses penyembuhan luka/pascaoperasi, serta menjaga daya tahan tubuh<br />\r\nEfek Samping :<br />\r\nUmumnya aman dikonsumsi; jarang menimbulkan gangguan pencernaan ringan<br />\r\nAturan Pakai :<br />\r\nDiminum 2-3 kapsul, 2-3 kali sehari, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3435;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCalcium Lactate (Kalsium Laktat) 500 mg<br />\r\nIndikasi :<br />\r\nMemenuhi kebutuhan kalsium harian dan memelihara kesehatan tulang<br />\r\nEfek Samping :<br />\r\nGangguan pencernaan ringan seperti kembung atau sembelit bila digunakan berlebihan<br />\r\nAturan Pakai :<br />\r\nDewasa: diminum tiap 8 jam. Anak 6-12 tahun: tiap 12 jam. Perbanyak minum air putih dan konsumsi buah serta sayur selama penggunaan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3451;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSimvastatin 20 mg<br />\r\nIndikasi :<br />\r\nMenurunkan kadar kolesterol jahat (LDL) dan trigliserida dalam darah, membantu mencegah penyakit jantung dan stroke<br />\r\nEfek Samping :<br />\r\nSakit kepala, nyeri otot, gangguan pencernaan; jarang, gangguan fungsi hati atau kerusakan otot (miopati)<br />\r\nAturan Pakai :<br />\r\nDiminum 1 kali sehari pada malam hari, sebaiknya pada jam yang sama setiap hari, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3523;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nRamuan herbal tradisional Tiongkok, antara lain Cnidium monnieri, Cortex Phellodendri, Radix Sophorae Flavescentis, Fructus Cnidii, Radix Angelicae Dahuricae, Rhizoma Atractylodis, Radix Stemonae, dan Cortex Dictamni<br />\r\nIndikasi :<br />\r\nDiklaim membantu meredakan gatal, eksim, psoriasis, dan infeksi jamur kulit ringan seperti panu/kurap<br />\r\nEfek Samping :<br />\r\nIritasi kulit, kemerahan, rasa panas, kulit kering, atau reaksi alergi; berisiko infeksi sekunder bila diaplikasikan pada kulit luka<br />\r\nAturan Pakai :<br />\r\nOleskan tipis pada area kulit yang gatal 2-3 kali sehari setelah dibersihkan; lakukan uji tempel pada area kecil terlebih dahulu untuk memeriksa reaksi alergi. PERHATIAN: produk ini belum terdaftar resmi di BPOM Indonesia, sehingga keamanan dan efektivitasnya belum teruji secara klinis; gunakan dengan hati-hati dan konsultasikan ke dokter/apoteker sebelum digunakan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3546;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSarung tangan medis sekali pakai berbahan nitrile, bebas lateks, ukuran L, non-obat<br />\r\nIndikasi :<br />\r\nMelindungi tangan dari kontaminasi/paparan cairan tubuh dan bahan kimia saat melakukan tindakan medis atau perawatan luka<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan reaksi alergi ringan pada individu yang sensitif terhadap bahan nitrile<br />\r\nAturan Pakai :<br />\r\nKenakan pada tangan yang bersih dan kering, gunakan sekali pakai untuk satu tindakan lalu buang<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3725;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nGentamicin Sulfate 0,3%<br />\r\nIndikasi :<br />\r\nAntibiotik untuk mengobati infeksi bakteri pada mata seperti konjungtivitis (mata merah) dan blefaritis<br />\r\nEfek Samping :<br />\r\nRasa perih atau iritasi sementara pada mata, pandangan kabur sesaat setelah pemakaian<br />\r\nAturan Pakai :<br />\r\nOleskan sedikit salep pada kelopak mata bagian dalam, 2-3 kali sehari atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3780;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAluminium Hidroksida, Magnesium Hidroksida, Simethicone<br />\r\nIndikasi :<br />\r\nMengatasi kelebihan asam lambung, maag, nyeri ulu hati, kembung, dan gangguan pencernaan<br />\r\nEfek Samping :<br />\r\nDapat menyebabkan diare (efek magnesium) atau sembelit (efek aluminium) bila digunakan berlebihan<br />\r\nAturan Pakai :<br />\r\nDikunyah 1-2 tablet, 3-4 kali sehari, 1 jam setelah makan dan menjelang tidur, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3815;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nEthacridine Lactate (Etakridin Laktat) 0,1%<br />\r\nIndikasi :<br />\r\nAntiseptik untuk membersihkan dan mencegah infeksi pada luka luar, luka lecet, atau luka pascaoperasi<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan iritasi ringan atau reaksi alergi pada kulit yang sensitif<br />\r\nAturan Pakai :<br />\r\nTuangkan atau basahi kasa dengan larutan, kompreskan atau bersihkan pada luka 2-3 kali sehari. Hanya untuk pemakaian luar<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3821;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMefenamic Acid (Asam Mefenamat) 500 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri ringan hingga sedang seperti sakit kepala, sakit gigi, nyeri otot dan sendi, serta nyeri haid<br />\r\nEfek Samping :<br />\r\nSakit kepala/pusing, sakit perut, mual, muntah, nyeri ulu hati, mengantuk, mulut kering, diare<br />\r\nAturan Pakai :<br />\r\nDewasa dan anak &gt;14 tahun: dosis awal 500 mg, dilanjutkan 250 mg tiap 6 jam. Diminum sesudah makan, tidak digunakan lebih dari 7 hari tanpa anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3860;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAcetylcysteine 200 mg<br />\r\nIndikasi :<br />\r\nMukolitik untuk mengencerkan dan mengeluarkan dahak pada batuk berdahak akibat gangguan saluran napas seperti bronkitis<br />\r\nEfek Samping :<br />\r\nMual, muntah, gangguan pencernaan; jarang, reaksi alergi seperti ruam atau sesak napas<br />\r\nAturan Pakai :<br />\r\nDewasa: 1 kapsul, 2-3 kali sehari. Diminum sesudah makan, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3956;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAluminium Hidroksida (Al(OH)3) 200 mg, Magnesium Hidroksida (Mg(OH)2) 200 mg<br />\r\nIndikasi :<br />\r\nMengatasi kelebihan asam lambung, maag, nyeri ulu hati, dan kembung<br />\r\nEfek Samping :<br />\r\nDapat menyebabkan diare (efek magnesium) atau sembelit (efek aluminium) bila digunakan berlebihan<br />\r\nAturan Pakai :<br />\r\nDikunyah 1-2 tablet, 3-4 kali sehari, 1 jam sebelum makan atau 2 jam sesudah makan dan menjelang tidur<br />\r\n&nbsp;</p>' WHERE `id_barang` = 3983;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nNatrium Diklofenak (Diclofenac Sodium) 50 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri dan peradangan pada artritis, nyeri otot, nyeri sendi, dan nyeri pascaoperasi<br />\r\nEfek Samping :<br />\r\nSakit perut, mual, gangguan pencernaan; jarang, gangguan fungsi hati/ginjal<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet, 2-3 kali sehari sesudah makan, atau sesuai resep dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4155;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPerban elastis (elastic crepe bandage) berbahan katun-elastis, non-obat<br />\r\nIndikasi :<br />\r\nUntuk membalut dan memberikan penyangga/kompresi pada area cedera seperti keseleo, terkilir, atau pasca cedera otot dan sendi<br />\r\nEfek Samping :<br />\r\nPembalutan yang terlalu kencang dapat mengganggu sirkulasi darah; longgarkan bila area membengkak, kebas, atau berubah warna<br />\r\nAturan Pakai :<br />\r\nBalutkan pada area yang cedera dengan tekanan sedang dari arah bawah ke atas, fiksasi ujungnya dengan klip/plester<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4168;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Vitamin A Palmitate 5.000 IU, Vitamin B1 2 mg, Vitamin B2 2 mg, Vitamin B6 2 mg, Vitamin C 50 mg, Vitamin D2 400 IU, Nicotinamide 10 mg, Calcium Pantothenate 5 mg<br />\r\nIndikasi :<br />\r\nMembantu memenuhi kebutuhan multivitamin pada masa pertumbuhan anak atau untuk mengatasi kekurangan vitamin<br />\r\nEfek Samping :<br />\r\nUmumnya aman dikonsumsi sesuai dosis; konsultasikan ke dokter bila timbul efek yang tidak diinginkan<br />\r\nAturan Pakai :<br />\r\nDewasa dan anak &gt;4 tahun: 5 ml sehari. Anak 1-4 tahun: 2,5 ml sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4198;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nVitamin D3 (Cholecalciferol) 400 IU per 1 ml (sesuai takaran tetes)<br />\r\nIndikasi :<br />\r\nMembantu memenuhi kebutuhan vitamin D3 untuk mendukung pertumbuhan tulang pada bayi dan anak<br />\r\nEfek Samping :<br />\r\nUmumnya aman pada dosis anjuran; kelebihan dosis jangka panjang berisiko hiperkalsemia<br />\r\nAturan Pakai :<br />\r\nTeteskan sesuai dosis anjuran (umumnya 1 tetes/hari setara 400 IU) langsung ke mulut atau dicampur makanan/susu, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4215;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMetamizole Sodium (Antalgin) 500 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri seperti sakit kepala dan sakit gigi, serta menurunkan demam<br />\r\nEfek Samping :<br />\r\nReaksi hipersensitivitas (agranulositosis), gangguan kulit, penurunan sel darah putih, reaksi alergi (gatal, ruam, sesak napas); jarang, anemia atau gangguan pembekuan darah<br />\r\nAturan Pakai :<br />\r\nDewasa dan anak &gt;12 tahun: 1 tablet, 3 kali sehari. Anak 6-12 tahun: &frac12; tablet, 3 kali sehari. Diminum sesudah makan untuk menghindari gangguan pencernaan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4219;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nVitamin E 30 IU, Vitamin C 500 mg, Vitamin B1 15 mg, Vitamin B6 25 mg, Vitamin B12 40 mcg, Zinc 20 mg<br />\r\nIndikasi :<br />\r\nMembantu memelihara daya tahan tubuh dan memenuhi kebutuhan vitamin serta mineral harian<br />\r\nEfek Samping :<br />\r\nReaksi hipersensitivitas pada individu yang sensitif terhadap salah satu kandungan<br />\r\nAturan Pakai :<br />\r\nDewasa dan anak &amp;ge;12 tahun: 1 tablet sehari, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4362;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nVitamin D3 (Cholecalciferol) 1000 IU<br />\r\nIndikasi :<br />\r\nMembantu memenuhi kebutuhan vitamin D3 untuk mendukung kesehatan tulang dan daya tahan tubuh<br />\r\nEfek Samping :<br />\r\nUmumnya aman pada dosis anjuran; kelebihan dosis jangka panjang berisiko hiperkalsemia<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet sehari setelah makan, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4394;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nNatrium Diklofenak (Diclofenac Sodium) 50 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri dan peradangan pada artritis, nyeri otot, nyeri sendi, dan nyeri pascaoperasi<br />\r\nEfek Samping :<br />\r\nSakit perut, mual, gangguan pencernaan; jarang, gangguan fungsi hati/ginjal<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet, 2-3 kali sehari sesudah makan, atau sesuai resep dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4460;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nStrip test elektrokimia untuk pengukuran kadar glukosa darah, digunakan bersama alat Easy Touch, non-obat<br />\r\nIndikasi :<br />\r\nUntuk memeriksa dan memantau kadar gula darah secara mandiri di rumah bagi penderita atau yang berisiko diabetes<br />\r\nEfek Samping :<br />\r\nTindakan tusuk jari (lancet) dapat menimbulkan nyeri ringan dan sedikit memar pada titik tusukan<br />\r\nAturan Pakai :<br />\r\nMasukkan strip ke alat Easy Touch, teteskan sampel darah dari ujung jari pada area strip, baca hasil pada layar alat<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4560;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nStrip test elektrokimia untuk pengukuran kadar asam urat darah, digunakan bersama alat Easy Touch, non-obat<br />\r\nIndikasi :<br />\r\nUntuk memeriksa dan memantau kadar asam urat darah secara mandiri di rumah<br />\r\nEfek Samping :<br />\r\nTindakan tusuk jari (lancet) dapat menimbulkan nyeri ringan dan sedikit memar pada titik tusukan<br />\r\nAturan Pakai :<br />\r\nMasukkan strip ke alat Easy Touch, teteskan sampel darah dari ujung jari pada area strip, baca hasil pada layar alat<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4561;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nStrip test elektrokimia untuk pengukuran kadar kolesterol total darah, digunakan bersama alat Easy Touch, non-obat<br />\r\nIndikasi :<br />\r\nUntuk memeriksa dan memantau kadar kolesterol total darah secara mandiri di rumah<br />\r\nEfek Samping :<br />\r\nTindakan tusuk jari (lancet) dapat menimbulkan nyeri ringan dan sedikit memar pada titik tusukan<br />\r\nAturan Pakai :<br />\r\nMasukkan strip ke alat Easy Touch, teteskan sampel darah dari ujung jari pada area strip, baca hasil pada layar alat<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4562;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Hydrotalcite 200 mg, Magnesium Hydroxide 150 mg, Simethicone 50 mg<br />\r\nIndikasi :<br />\r\nMeredakan gejala maag, nyeri ulu hati, perut kembung, dan kelebihan asam lambung<br />\r\nEfek Samping :<br />\r\nSembelit, diare ringan, atau mual (jarang terjadi)<br />\r\nAturan Pakai :<br />\r\nKocok dahulu sebelum digunakan. Diminum 1-2 sendok takar (5-10 ml), 3-4 kali sehari sesudah makan dan sebelum tidur, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4651;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nVitamin B1 (Thiamine mononitrate) 100 mg, Vitamin B6 (Pyridoxine HCl) 200 mg, Vitamin B12 (Cyanocobalamin) 200 mcg<br />\r\nIndikasi :<br />\r\nMembantu memenuhi kebutuhan vitamin B, meredakan gejala gangguan saraf tepi (neuropati) seperti kesemutan dan nyeri saraf<br />\r\nEfek Samping :<br />\r\nMual, ruam kulit, atau reaksi alergi (jarang terjadi) terutama pada penggunaan dosis tinggi jangka panjang<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet per hari, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4696;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nAlat pengukur multifungsi (meter device) untuk kadar Glukosa, Kolesterol, dan Asam Urat darah, menggunakan strip test terpisah untuk tiap parameter, non-obat<br />\r\nIndikasi :<br />\r\nUntuk memeriksa dan memantau kadar gula darah, kolesterol, dan asam urat secara mandiri di rumah<br />\r\nEfek Samping :<br />\r\nTindakan tusuk jari (lancet) dapat menimbulkan nyeri ringan dan sedikit memar pada titik tusukan<br />\r\nAturan Pakai :<br />\r\nPasang strip sesuai parameter yang ingin diperiksa, teteskan sampel darah dari ujung jari, baca hasil pada layar alat; gunakan baterai sesuai petunjuk manual<br />\r\n&nbsp;</p>' WHERE `id_barang` = 4803;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nChlorpheniramine Maleate (CTM) 4 mg<br />\r\nIndikasi :<br />\r\nMeredakan gejala alergi seperti bersin-bersin, gatal-gatal, biduran (urtikaria), dan pilek alergi<br />\r\nEfek Samping :<br />\r\nMengantuk, mulut kering, pusing<br />\r\nAturan Pakai :<br />\r\nDewasa: 1 tablet, 3-4 kali sehari. Hindari mengemudi atau mengoperasikan mesin setelah minum obat ini<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5045;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTermometer digital dengan ujung sensor fleksibel, non-obat, alat kesehatan<br />\r\nIndikasi :<br />\r\nUntuk mengukur suhu tubuh guna mendeteksi demam pada anak maupun dewasa<br />\r\nEfek Samping :<br />\r\nTidak memiliki efek samping; pastikan ujung sensor bersih sebelum dan sesudah digunakan<br />\r\nAturan Pakai :<br />\r\nTempatkan ujung sensor di ketiak, mulut, atau rektal (sesuai jenis pengukuran), tunggu hingga alat berbunyi, lalu baca hasil pada layar<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5296;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nMetamizole Sodium (Antalgin) 500 mg, Thiamine Nitrate (Vitamin B1) 50 mg, Pyridoxine HCl (Vitamin B6) 10 mg, Cyanocobalamin (Vitamin B12) 10 mcg, Kafein 50 mg<br />\r\nIndikasi :<br />\r\nMeredakan nyeri berat akibat gangguan saraf (neuralgia)<br />\r\nEfek Samping :<br />\r\nMual, muntah, nyeri perut, pusing, tekanan darah rendah; jarang, gangguan sel darah atau reaksi alergi berat<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet, 3 kali sehari (maksimal 4 tablet/hari), bersama makanan, sesuai resep dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5303;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nParacetamol 650 mg<br />\r\nIndikasi :<br />\r\nMeredakan demam dan nyeri ringan hingga sedang seperti sakit kepala dan sakit gigi<br />\r\nEfek Samping :<br />\r\nJarang; dapat mengiritasi lambung atau reaksi alergi (ruam, gatal) bila digunakan berlebihan; risiko kerusakan hati pada penggunaan jangka panjang/overdosis<br />\r\nAturan Pakai :<br />\r\nDewasa: 1-2 kaplet, 3-4 kali sehari. Anak 6-12 tahun: &frac12;-1 kaplet, 3-4 kali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5335;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nSalbutamol Sulfate setara Salbutamol 2,5 mg per 2,5 ml<br />\r\nIndikasi :<br />\r\nMelegakan saluran napas pada serangan asma dan penyakit paru obstruktif kronik (PPOK) dengan cara dihirup menggunakan alat nebulizer<br />\r\nEfek Samping :<br />\r\nJantung berdebar, tremor (gemetar tangan), sakit kepala, gelisah<br />\r\nAturan Pakai :<br />\r\nDigunakan dengan alat nebulizer sesuai dosis dan anjuran dokter, umumnya 1 unit dose (2,5 ml) dihirup 3-4 kali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5401;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nClindamycin HCl setara Clindamycin 300 mg<br />\r\nIndikasi :<br />\r\nAntibiotik untuk mengatasi infeksi bakteri serius, termasuk infeksi kulit, tulang, sendi, dan saluran pernapasan<br />\r\nEfek Samping :<br />\r\nMual, muntah, diare, rasa seperti logam di mulut<br />\r\nAturan Pakai :<br />\r\nDiminum sesuai resep dokter (umumnya tiap 6-8 jam), dihabiskan meski gejala sudah membaik agar tidak terjadi resistensi bakteri<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5415;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nDexamethasone 0,5 mg, Dexchlorpheniramine Maleate 2 mg<br />\r\nIndikasi :<br />\r\nMeredakan reaksi alergi berat seperti rhinitis alergi, asma kronis, dermatitis kontak/atopik, dan reaksi alergi obat<br />\r\nEfek Samping :<br />\r\nRetensi cairan, gangguan pencernaan, nafsu makan meningkat, pandangan kabur, mulut kering, mengantuk<br />\r\nAturan Pakai :<br />\r\nDewasa: 1-2 tablet, 4 kali sehari. Anak: &frac12; tablet, 3-4 kali sehari. Diminum bersama makanan, sesuai resep dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5416;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nParacetamol 650 mg<br />\r\nIndikasi :<br />\r\nMeredakan demam dan nyeri ringan hingga sedang, termasuk nyeri akibat flu, pasca imunisasi, atau pasca operasi gigi (tonsilektomi)<br />\r\nEfek Samping :<br />\r\nReaksi hematologi, reaksi kulit, dan reaksi alergi lainnya (jarang); risiko kerusakan hati pada penggunaan jangka panjang/overdosis<br />\r\nAturan Pakai :<br />\r\nDewasa: 1-2 tablet, 3-4 kali sehari (maksimal 8 tablet/hari). Anak 7-12 tahun: &frac12;-1 tablet, 3-4 kali sehari (maksimal 4 tablet/hari)<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5485;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap 5 ml mengandung Paracetamol 250 mg, Pseudoephedrine HCl 15 mg, Chlorpheniramine Maleate 1 mg, Dextromethorphan HBr 7,5 mg<br />\r\nIndikasi :<br />\r\nMeredakan gejala flu seperti demam, sakit kepala, hidung tersumbat, bersin-bersin, disertai batuk<br />\r\nEfek Samping :<br />\r\nMengantuk, pusing, mulut kering, jantung berdebar, gangguan pencernaan; risiko kerusakan hati bila paracetamol digunakan berlebihan<br />\r\nAturan Pakai :<br />\r\nDewasa dan anak &gt;12 tahun: 3-4 sendok takar, 3 kali sehari. Anak 6-12 tahun: 2 sendok takar, 3 kali sehari. Anak 2-6 tahun: 1 sendok takar, 3 kali sehari (1 sendok takar = 5 ml)<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5557;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap tablet mengandung Vitamin D3 (Cholecalciferol) 400 IU, Vitamin K2 (Menaquinone) 30 mcg<br />\r\nIndikasi :<br />\r\nMembantu memenuhi kebutuhan vitamin D3 dan K2 untuk mendukung kesehatan tulang<br />\r\nEfek Samping :<br />\r\nUmumnya aman pada dosis anjuran; tidak dianjurkan bersama obat pengencer darah seperti warfarin<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet sehari setelah makan, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5902;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nParacetamol 500 mg<br />\r\nIndikasi :<br />\r\nMenurunkan demam dan meredakan nyeri ringan hingga sedang seperti sakit kepala dan sakit gigi<br />\r\nEfek Samping :<br />\r\nMual, muntah, ruam kulit, gatal-gatal; risiko kerusakan hati pada penggunaan jangka panjang/berlebihan<br />\r\nAturan Pakai :<br />\r\nDewasa: 1-2 kaplet, 3-4 kali sehari. Anak 6-12 tahun: &frac12;-1 kaplet, 3-4 kali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 5983;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nVitamin B1 (Thiamine), Vitamin B2 (Riboflavin), Vitamin B6 (Pyridoxine), Vitamin B12 (Cyanocobalamin), Nicotinamide<br />\r\nIndikasi :<br />\r\nMembantu memenuhi kebutuhan vitamin B kompleks harian dan menjaga fungsi sistem saraf serta metabolisme tubuh<br />\r\nEfek Samping :<br />\r\nUmumnya aman dikonsumsi; jarang menimbulkan gangguan pencernaan ringan atau reaksi alergi<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet, 1-3 kali sehari, sesudah makan, atau sesuai anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6005;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nStrip test imunokromatografi untuk mendeteksi hormon hCG (human Chorionic Gonadotropin) dalam urine, non-obat<br />\r\nIndikasi :<br />\r\nUntuk mendeteksi kehamilan secara mandiri di rumah<br />\r\nEfek Samping :<br />\r\nHasil dapat kurang akurat bila pemeriksaan dilakukan terlalu dini atau tidak sesuai petunjuk<br />\r\nAturan Pakai :<br />\r\nCelupkan strip pada urine (sebaiknya urine pagi hari) sampai batas yang ditentukan, tunggu beberapa menit, lalu baca hasil sesuai petunjuk kemasan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6042;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTranexamic Acid (Asam Tranexamat) 500 mg<br />\r\nIndikasi :<br />\r\nMenghentikan atau mengurangi perdarahan, seperti perdarahan akibat wasir (hemoroid) atau menstruasi berlebih (menorrhagia)<br />\r\nEfek Samping :<br />\r\nMual, muntah, diare, atau pusing (jarang terjadi); perlu kehati-hatian pada pasien dengan riwayat gangguan pembekuan darah/trombosis<br />\r\nAturan Pakai :<br />\r\nDiminum sesuai anjuran dokter, umumnya 1 tablet 2-3 kali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6083;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nParacetamol 500 mg, Dextromethorphan HBr 15 mg, Pseudoephedrine HCl 20 mg, Chlorpheniramine Maleate 2 mg<br />\r\nIndikasi :<br />\r\nMeredakan gejala flu seperti demam, sakit kepala, bersin, hidung tersumbat, dan batuk tidak berdahak<br />\r\nEfek Samping :<br />\r\nMengantuk, gangguan pencernaan, atau mual<br />\r\nAturan Pakai :<br />\r\nDewasa: 1 tablet, 3 kali sehari. Anak 6-12 tahun: 1/2 tablet, 3 kali sehari. Obat keras, gunakan sesuai resep/anjuran dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6084;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPovidone Iodine 5%<br />\r\nIndikasi :<br />\r\nAntiseptik untuk membersihkan dan mencegah infeksi pada luka kecil, lecet, atau goresan pada kulit<br />\r\nEfek Samping :<br />\r\nIritasi atau rasa perih ringan pada area yang disemprot; reaksi alergi pada individu yang sensitif terhadap iodine<br />\r\nAturan Pakai :<br />\r\nSemprotkan pada luka yang bersih dari jarak dekat, 1-2 kali sehari atau sesuai kebutuhan. Hanya untuk pemakaian luar<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6086;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap sendok takar mengandung ekstrak Curcuma xanthorrhiza (Temulawak) 10 mg, Vitamin A 850 IU, Vitamin B1 3 mg, Vitamin B2 1,5 mg, Vitamin B6 0,5 mg, Vitamin B12 5 mcg, Vitamin D 100 IU, Calcium Pantothenate 5 mg, Calcium Glycerophosphate 100 mg, Cod Liver Oil (Minyak Ikan Kod) 2,5 mg<br />\r\nIndikasi :<br />\r\nMeningkatkan nafsu makan, menjaga kesehatan fungsi hati, membantu menambah berat badan, dan memenuhi kebutuhan vitamin dalam tubuh<br />\r\nEfek Samping :<br />\r\nIritasi lambung, mual, atau muntah pada penggunaan jangka panjang<br />\r\nAturan Pakai :<br />\r\nDewasa: 3 kali sehari 1 sendok takar. Anak 1-5 tahun: 1 kali sehari 1 sendok takar. Anak 6-12 tahun: 2 kali sehari 1 sendok takar. Dapat diminum sebelum atau sesudah makan<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6087;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPyrantel Pamoate setara Pirantel base 125 mg/5 ml<br />\r\nIndikasi :<br />\r\nUntuk mengatasi infeksi cacing gelang (Ascaris lumbricoides), cacing kremi (Enterobius vermicularis), dan cacing tambang<br />\r\nEfek Samping :<br />\r\nMual, muntah, diare, sakit kepala, atau pusing (jarang terjadi)<br />\r\nAturan Pakai :<br />\r\nKocok dahulu sebelum digunakan. Dosis 10 mg/kgBB diminum sekali sehari (dosis tunggal), dapat diulang setelah 2 minggu bila perlu, atau sesuai anjuran dokter/apoteker<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6088;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap sendok takar mengandung Curcuminoid 2 mg, Carotene 10% 4 mg, Vitamin B1 3 mg, Vitamin B2 2 mg, Vitamin B6 5 mg, Vitamin B12 5 mcg, Dexpanthenol 3 mg, DHA Powder 32 mg, Prebiotik (Fructo Oligosaccharide) 500 mg<br />\r\nIndikasi :<br />\r\nMeningkatkan nafsu makan pada anak serta membantu menjaga kesehatan saluran pencernaan<br />\r\nEfek Samping :<br />\r\nBelum ada laporan efek samping yang berarti; hentikan bila timbul reaksi alergi<br />\r\nAturan Pakai :<br />\r\nUsia 6 bulan-1 tahun: &frac12; sendok takar (2,5 ml), 1 kali sehari. Usia 1-6 tahun: 1 sendok takar (5 ml), 1 kali sehari. Usia 7-12 tahun: 1 sendok takar (5 ml), 2 kali sehari. Dewasa: 1 sendok takar (5 ml), 3 kali sehari<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6089;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nCaptopril 25 mg<br />\r\nIndikasi :<br />\r\nObat golongan ACE inhibitor untuk menurunkan tekanan darah tinggi (hipertensi) dan gagal jantung<br />\r\nEfek Samping :<br />\r\nBatuk kering, pusing, sakit kepala, kelelahan, atau ruam kulit<br />\r\nAturan Pakai :<br />\r\nDiminum 1 tablet, 2-3 kali sehari, sebaiknya 1 jam sebelum makan, atau sesuai anjuran dokter. Obat keras, gunakan sesuai resep dokter<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6090;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nTiap tablet mengandung Ferrous Gluconate (setara zat besi 12,45 mg), Asam Folat 500 mcg, Vitamin B1 1,5 mg, Vitamin B2 0,25 mg, Nicotinamide 10 mg, Vitamin B6 0,25 mg, Vitamin C 12,5 mg, Calcium Pantothenate 1,5 mg, Copper Gluconate<br />\r\nIndikasi :<br />\r\nMemenuhi kebutuhan zat besi dan vitamin B kompleks, membantu masa pemulihan, serta membantu menjaga daya tahan tubuh<br />\r\nEfek Samping :<br />\r\nMual, nyeri lambung, sembelit, diare, atau kram perut<br />\r\nAturan Pakai :<br />\r\nDewasa: 1-2 tablet, 3 kali sehari. Anak: 1 tablet, 3 kali sehari. Hentikan bila timbul reaksi alergi<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6091;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPlester luka berbahan dasar kain elastis (fabric strip) dengan bantalan penyerap steril, non-obat<br />\r\nIndikasi :<br />\r\nUntuk menutup dan melindungi luka kecil/lecet dari kotoran dan gesekan<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan iritasi kulit ringan pada kulit yang sensitif terhadap bahan perekat<br />\r\nAturan Pakai :<br />\r\nBersihkan luka terlebih dahulu, tempelkan plester menutupi seluruh permukaan luka, ganti secara berkala terutama bila basah/kotor<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6092;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nJarum lancet steril sekali pakai untuk pengambilan sampel darah kapiler, non-obat<br />\r\nIndikasi :<br />\r\nUntuk menusuk ujung jari guna mengambil sampel darah pada pemeriksaan gula darah, asam urat, atau kolesterol<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan nyeri ringan dan sedikit memar pada titik tusukan<br />\r\nAturan Pakai :<br />\r\nPasang lancet pada alat autoclick/lancing device, tekan pada ujung jari yang telah dibersihkan alkohol, gunakan satu lancet untuk sekali pakai lalu buang<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6093;
UPDATE `barang` SET `ket_barang` = '<p>Komposisi :<br />\r\nPlester perekat luka (adhesive tape) berbahan kain/kertas dengan lapisan perekat hipoalergenik, non-obat<br />\r\nIndikasi :<br />\r\nUntuk memfiksasi kasa atau perban pada luka, serta sebagai plester serbaguna dalam perawatan luka<br />\r\nEfek Samping :<br />\r\nDapat menimbulkan iritasi kulit ringan pada kulit yang sensitif terhadap bahan perekat<br />\r\nAturan Pakai :<br />\r\nPotong sesuai kebutuhan, tempelkan pada kasa/perban dan kulit di sekitarnya untuk memfiksasi<br />\r\n&nbsp;</p>' WHERE `id_barang` = 6094;
